files.content:
:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #eaeaea;
  --muted: #a0a0b0;
  --radius: 12px;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  background-image: 
    linear-gradient(45deg, rgba(233,69,96,0.05) 25%, transparent 25%),
    linear-gradient(-45deg, rgba(233,69,96,0.05) 25%, transparent 25%),
    linear-gradient(45deg, transparent 75%, rgba(233,69,96,0.05) 75%),
    linear-gradient(-45deg, transparent 75%, rgba(233,69,96,0.05) 75%);
  background-size: 20px 20px;
  background-position: 0 0, 0 10px, 10px -10px, -10px 0px;
  font-family: var(--font);
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card);
  border-radius: var(--radius);
  padding: 32px 24px;
  width: 100%;
  max-width: 400px;
  text-align: center;
  box-shadow: 0 8px 32px rgba(0,0,0,0.4);
  border: 2px solid rgba(233,69,96,0.2);
}

h1 {
  font-size: 1.25rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: 8px;
}

.mode-indicator {
  font-size: 0.875rem;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.15em;
  margin-bottom: 16px;
}

.timer {
  font-size: clamp(3rem, 18vw, 5rem);
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.05em;
  color: var(--text);
  margin-bottom: 24px;
  line-height: 1;
  text-shadow: 0 0 20px rgba(233,69,96,0.3);
}

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  margin-bottom: 20px;
  flex-wrap: wrap;
}

.btn {
  font-family: var(--font);
  font-size: 1rem;
  font-weight: 600;
  padding: 12px 24px;
  border: 2px solid var(--accent);
  border-radius: 8px;
  background: transparent;
  color: var(--text);
  cursor: pointer;
  transition: background 0.15s, color 0.15s, transform 0.1s;
  min-width: 100px;
}

.btn:hover {
  background: rgba(233,69,96,0.15);
}

.btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.btn:active {
  transform: scale(0.96);
  background: rgba(233,69,96,0.3);
}

.btn.primary {
  background: var(--accent);
  color: var(--bg);
}

.btn.primary:hover {
  background: #f05a72;
}

.btn.primary:active {
  background: #d13a52;
}

.mode-switch {
  display: flex;
  gap: 8px;
  justify-content: center;
  margin-bottom: 20px;
}

.btn.small {
  font-size: 0.875rem;
  padding: 8px 16px;
  min-width: auto;
  border-color: var(--muted);
  color: var(--muted);
}

.btn.small:hover {
  border-color: var(--accent);
  color: var(--text);
}

.btn.small.active {
  border-color: var(--accent);
  background: var(--accent);
  color: var(--bg);
}

.hint {
  font-size: 0.8125rem;
  color: var(--muted);
  margin-top: 8px;
}

@media (max-width: 360px) {
  .card { padding: 24px 16px; }
  .btn { padding: 10px 16px; min-width: 80px; }
  .btn.small { padding: 6px 12px; font-size: 0.8125rem; }
  .controls { gap: 8px; }
}

(function () {
  'use strict';

  var WORK_SECONDS = 25 * 60;
  var BREAK_SECONDS = 5 * 60;

  var timerEl = document.getElementById('timer');
  var modeEl = document.getElementById('mode-indicator');
  var startPauseBtn = document.getElementById('start-pause');
  var resetBtn = document.getElementById('reset');
  var workBtn = document.getElementById('mode-work');
  var breakBtn = document.getElementById('mode-break');

  var mode = 'work';
  var remaining = WORK_SECONDS;
  var running = false;
  var intervalId = null;
  var endTime = 0;

  function formatTime(secs) {
    var m = Math.floor(secs / 60);
    var s = secs % 60;
    return (m < 10 ? '0' : '') + m + ':' + (s < 10 ? '0' : '') + s;
  }

  function render() {
    timerEl.textContent = formatTime(remaining);
    modeEl.textContent = mode === 'work' ? 'Work' : 'Break';
    startPauseBtn.textContent = running ? 'Pause' : 'Start';
    startPauseBtn.setAttribute('aria-label', running ? 'Pause timer' : 'Start timer');
    document.title = formatTime(remaining) + ' - ' + (mode === 'work' ? 'Work' : 'Break');
  }

  function setMode(newMode) {
    mode = newMode;
    remaining = mode === 'work' ? WORK_SECONDS : BREAK_SECONDS;
    stop();
    workBtn.classList.toggle('active', mode === 'work');
    breakBtn.classList.toggle('active', mode === 'break');
    workBtn.setAttribute('aria-pressed', mode === 'work' ? 'true' : 'false');
    breakBtn.setAttribute('aria-pressed', mode === 'break' ? 'true' : 'false');
    render();
  }

  function tick() {
    var now = Date.now();
    var secsLeft = Math.max(0, Math.round((endTime - now) / 1000));
    if (secsLeft !== remaining) {
      remaining = secsLeft;
      render();
    }
    if (remaining <= 0) {
      stop();
      // Auto-switch mode on completion
      setMode(mode === 'work' ? 'break' : 'work');
    }
  }

  function start() {
    if (running) return;
    running = true;
    endTime = Date.now() + remaining * 1000;
    intervalId = setInterval(tick, 250);
    render();
  }

  function stop() {
    if (!running) return;
    running = false;
    clearInterval(intervalId);
    intervalId = null;
    render();
  }

  function toggle() {
    if (running) {
      stop();
    } else {
      start();
    }
  }

  function reset() {
    stop();
    remaining = mode === 'work' ? WORK_SECONDS : BREAK_SECONDS;
    render();
  }

  startPauseBtn.addEventListener('click', toggle);
  resetBtn.addEventListener('click', reset);
  workBtn.addEventListener('click', function () { setMode('work'); });
  breakBtn.addEventListener('click', function () { setMode('break'); });

  document.addEventListener('keydown', function (e) {
    if (e.target.tagName === 'BUTTON') return;
    if (e.code === 'Space') {
      e.preventDefault();
      toggle();
    } else if (e.key === 'r' || e.key === 'R') {
      reset();
    }
  });

  render();
})();
